pug:
table.row.text-block(role='presentation')
    tr
        td.text-cell
            h2.subtitle {{ subtitle }}
            p.body {{ body }}

styl:
.row.text-block td.text-cell { padding: 16px 32px 24px; text-align: left; }
.row.text-block h2.subtitle { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 700; font-size: 20px; line-height: 1.3; color: {{ title_color }}; margin: 0 0 12px; padding: 0; }
.row.text-block p.body { font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 400; font-size: 16px; line-height: 1.5; color: {{ body_color }}; margin: 0; padding: 0; }
